// ─── File: ObservabilityDemo.java ───
// Runnable demo. In a real project each class is its own file under the packages above.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ObservabilityDemo {

    private static final Logger log = Logger.getLogger("observability");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BusinessMetrics metrics = new BusinessMetrics();

        // The accidental misconfiguration: settlement disabled.
        FeatureFlags brokenFlags = new FeatureFlags(false);
        PaymentService broken = new PaymentService(brokenFlags, metrics);

        log.info("=== Friday deploy: settlement flag accidentally OFF ===");
        for (int i = 0; i < 5; i++) {
            broken.initiate("SAV2001", new BigDecimal("50000"), false);
        }

        // Per-service technical view: everything looks fine.
        TechnicalHealth.report();

        // Business metric view: the product is clearly broken.
        metrics.report();

        // Synthetic journey: runs a full end-to-end test transfer and asserts completion.
        SyntheticJourney probe = new SyntheticJourney(broken);
        probe.probe();   // fires a SEVERE alert because completion fails

        // Now fix the flag and show the healthy path.
        log.info("=== Ops flips settlement flag back ON ===");
        PaymentService fixed = new PaymentService(new FeatureFlags(true), metrics);
        SyntheticJourney goodProbe = new SyntheticJourney(fixed);
        goodProbe.probe();   // passes
    }
}

// ─── Would be in config/FeatureFlags.java ───
class FeatureFlags {
    final boolean settlementEnabled;
    FeatureFlags(boolean settlementEnabled) { this.settlementEnabled = settlementEnabled; }
}

// ─── Would be in model/Payment.java ───
class Payment {
    final String paymentId;
    final String fromAccount;
    final BigDecimal amount;
    String status;            // INITIATED, COMPLETED, FAILED
    final boolean synthetic;
    Payment(String paymentId, String fromAccount, BigDecimal amount, boolean synthetic) {
        this.paymentId = paymentId; this.fromAccount = fromAccount;
        this.amount = amount; this.status = "INITIATED"; this.synthetic = synthetic;
    }
}

// ─── Would be in metrics/BusinessMetrics.java ───
class BusinessMetrics {
    private static final Logger log = Logger.getLogger("observability");
    private int initiated = 0;
    private int completed = 0;
    void recordInitiated(boolean synthetic) { if (!synthetic) initiated++; }
    void recordCompleted(boolean synthetic) { if (!synthetic) completed++; }
    double completionRate() { return initiated == 0 ? 1.0 : (double) completed / initiated; }
    void report() {
        double rate = completionRate();
        if (rate < 0.95) {
            log.severe(() -> String.format(
                "BUSINESS METRIC ALERT: payment completion rate=%.0f%% (initiated=%d completed=%d) — PRODUCT BROKEN",
                rate * 100, initiated, completed));
        } else {
            log.info(() -> String.format("completion rate=%.0f%% healthy", rate * 100));
        }
    }
}

// ─── Would be in metrics/TechnicalHealth.java ───
class TechnicalHealth {
    private static final Logger log = Logger.getLogger("observability");
    static void report() {
        // Everything green — this is exactly the misleading view.
        log.info("TECHNICAL HEALTH: payment-service UP, cpu=22%, mem=40%, 5xx=0.0% — all GREEN");
    }
}

// ─── Would be in service/PaymentService.java ───
class PaymentService {
    private static final Logger log = Logger.getLogger("observability");
    private final FeatureFlags flags;
    private final BusinessMetrics metrics;
    private final Map<String, Payment> store = new LinkedHashMap<>();
    PaymentService(FeatureFlags flags, BusinessMetrics metrics) { this.flags = flags; this.metrics = metrics; }

    // Returns the payment. Note: ALWAYS returns success (no exception, HTTP 200).
    Payment initiate(String fromId, BigDecimal amount, boolean synthetic) {
        String id = "PAY-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        Payment p = new Payment(id, fromId, amount, synthetic);
        store.put(id, p);
        metrics.recordInitiated(synthetic);

        if (flags.settlementEnabled) {
            p.status = "COMPLETED";
            metrics.recordCompleted(synthetic);
        } else {
            // Silent business failure: stays INITIATED forever, but we still "succeed".
            log.fine(() -> "settlement disabled; payment " + id + " stuck INITIATED");
        }
        return p;   // caller sees HTTP 200 regardless
    }

    Payment find(String id) { return store.get(id); }
}

// ─── Would be in synthetic/SyntheticJourney.java ───
class SyntheticJourney {
    private static final Logger log = Logger.getLogger("observability");
    private final PaymentService paymentService;
    SyntheticJourney(PaymentService paymentService) { this.paymentService = paymentService; }

    // Runs the full user flow as a probe and asserts the business OUTCOME.
    void probe() {
        Payment p = paymentService.initiate("SYNTH-0001", new BigDecimal("1"), true);
        // Assert the end-to-end outcome, NOT the HTTP status.
        if (!"COMPLETED".equals(paymentService.find(p.paymentId).status)) {
            log.severe(() -> "SYNTHETIC JOURNEY FAILED: test payment " + p.paymentId
                    + " did not reach COMPLETED — product broken (all probes were GREEN!)");
        } else {
            log.info(() -> "SYNTHETIC JOURNEY OK: test payment " + p.paymentId + " COMPLETED end-to-end");
        }
    }
}

// ─── Would be in config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
